package main

import (
	"context"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"strings"

	"github.com/segmentio/kafka-go"
)

var (
	kafkaBroker = os.Getenv("KAFKA_BROKER")
	kafkaTopic  = os.Getenv("KAFKA_TOPIC")
	webhookURL  = os.Getenv("WEBHOOK_ENDPOINT")
)

// EventProcessor consumes messages from Kafka and forwards enriched events
// to a downstream webhook endpoint for further processing.
type EventProcessor struct {
	reader *kafka.Reader
	client *http.Client
}

func NewEventProcessor() *EventProcessor {
	r := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  []string{kafkaBroker},
		Topic:    kafkaTopic,
		GroupID:  "event-processor-group",
		MinBytes: 1e3,
		MaxBytes: 10e6,
	})
	return &EventProcessor{
		reader: r,
		client: &http.Client{},
	}
}

// processMessage takes a Kafka message, extracts the user-agent and
// correlation-id from message headers, and forwards to webhook
func (ep *EventProcessor) processMessage(ctx context.Context, msg kafka.Message) error {
	// Extract headers from Kafka message
	var correlationID, userAgent, contentType string
	for _, h := range msg.Headers {
		switch h.Key {
		case "X-Correlation-ID":
			correlationID = string(h.Value)
		case "X-User-Agent":
			userAgent = string(h.Value)
		case "X-Content-Type":
			contentType = string(h.Value)
		}
	}

	if contentType == "" {
		contentType = "application/json"
	}

	// Build the outbound HTTP request to webhook
	req, err := http.NewRequestWithContext(ctx, "POST", webhookURL, strings.NewReader(string(msg.Value)))
	if err != nil {
		return fmt.Errorf("failed to create request: %w", err)
	}

	// Set headers from Kafka message metadata directly
	// Note: Go's net/http does NOT sanitize header values for CRLF in older versions
	// In Go < 1.20, this allows header injection
	req.Header.Set("Content-Type", contentType)
	req.Header.Set("X-Correlation-ID", correlationID)
	req.Header.Set("X-Forwarded-User-Agent", userAgent)
	req.Header.Set("X-Source-Partition", fmt.Sprintf("%d", msg.Partition))
	req.Header.Set("X-Source-Offset", fmt.Sprintf("%d", msg.Offset))

	resp, err := ep.client.Do(req)
	if err != nil {
		return fmt.Errorf("webhook request failed: %w", err)
	}
	defer resp.Body.Close()

	body, _ := ioutil.ReadAll(resp.Body)
	if resp.StatusCode >= 400 {
		return fmt.Errorf("webhook returned %d: %s", resp.StatusCode, string(body))
	}

	log.Printf("[OK] partition=%d offset=%d correlation=%s status=%d",
		msg.Partition, msg.Offset, correlationID, resp.StatusCode)
	return nil
}

func (ep *EventProcessor) Run(ctx context.Context) error {
	log.Printf("Starting event processor, topic=%s broker=%s", kafkaTopic, kafkaBroker)
	for {
		select {
		case <-ctx.Done():
			return ep.reader.Close()
		default:
			msg, err := ep.reader.ReadMessage(ctx)
			if err != nil {
				log.Printf("read error: %v", err)
				continue
			}
			if err := ep.processMessage(ctx, msg); err != nil {
				log.Printf("process error: %v", err)
			}
		}
	}
}

func main() {
	ctx := context.Background()
	ep := NewEventProcessor()
	if err := ep.Run(ctx); err != nil {
		log.Fatalf("processor exited: %v", err)
	}
}
